func (rewritingRequestsCodec) buildConfigsPatch(ctx context.Context, configured, planned types.Object, diagnostics diag.Diagnostics) (wafmodule.Patch, diag.Diagnostics) {
	if configured.IsNull() {
		return rewritingRequestsPatch{}, diagnostics
	}
	if configured.IsUnknown() || planned.IsNull() || planned.IsUnknown() {
		diagnostics.AddError("Unknown rewriting requests configuration", "The configs block must be known during apply.")
		return nil, diagnostics
	}

	var configValues, planValues rewritingRequestsConfigsModel
	diagnostics.Append(configured.As(ctx, &configValues, basetypes.ObjectAsOptions{})...)
	diagnostics.Append(planned.As(ctx, &planValues, basetypes.ObjectAsOptions{})...)
	if diagnostics.HasError() {
		return nil, diagnostics
	}

	patch := rewritingRequestsPatch{}
	patch.IDentifyOriginalIp, diagnostics = rewritingRequestsConfiguredBool(configValues.IDentifyOriginalIp, planValues.IDentifyOriginalIp, "identify_original_ip", diagnostics)
	patch.SourcePort, diagnostics = rewritingRequestsConfiguredBool(configValues.SourcePort, planValues.SourcePort, "source_port", diagnostics)
	patch.Status, diagnostics = rewritingRequestsConfiguredBool(configValues.Status, planValues.Status, "status", diagnostics)
	patch.XForwardedFor, diagnostics = rewritingRequestsConfiguredBool(configValues.XForwardedFor, planValues.XForwardedFor, "x_forwarded_for", diagnostics)
	patch.XForwardedPort, diagnostics = rewritingRequestsConfiguredBool(configValues.XForwardedPort, planValues.XForwardedPort, "x_forwarded_port", diagnostics)
	patch.XHeader, diagnostics = rewritingRequestsConfiguredString(configValues.XHeader, planValues.XHeader, "x_header", diagnostics)
	patch.XRealIp, diagnostics = rewritingRequestsConfiguredBool(configValues.XRealIp, planValues.XRealIp, "x_real_ip", diagnostics)

	patch.RuleList, diagnostics = rewritingRequestsBuildConfiguredRuleList(ctx, configValues.RuleList, planValues.RuleList, diagnostics)
	if diagnostics.HasError() {
		return nil, diagnostics
	}
	return patch, diagnostics
}

func (rewritingRequestsCodec) ValidateResult(ctx context.Context, result client.WAFModuleResult, ownership wafmodule.OwnershipContext) diag.Diagnostics {
	_, diagnostics := rewritingRequestsDecodeScalars(result)
	owned, ownershipDiagnostics := rewritingRequestsOwnership(ctx, result.Template, ownership)
	diagnostics.Append(ownershipDiagnostics...)
	if diagnostics.HasError() {
		return diagnostics
	}

	if owned.RuleList {
		_, itemDiagnostics := rewritingRequestsDecodeRuleList(result.Configs["rule_list"])
		diagnostics.Append(itemDiagnostics...)
	}
	return diagnostics
}

func (rewritingRequestsCodec) Flatten(ctx context.Context, epID string, result client.WAFModuleResult, ownership wafmodule.OwnershipContext) (any, diag.Diagnostics) {
	model := rewritingRequestsResourceModel{
		EPID:     types.StringValue(epID),
		Template: types.BoolValue(result.Template),
		Configs:  types.ObjectNull(rewritingRequestsConfigAttributeTypes),
	}
	scalars, diagnostics := rewritingRequestsDecodeScalars(result)
	if diagnostics.HasError() || result.Template {
		return &model, diagnostics
	}
	owned, ownershipDiagnostics := rewritingRequestsOwnership(ctx, result.Template, ownership)
	diagnostics.Append(ownershipDiagnostics...)
	if diagnostics.HasError() {
		return nil, diagnostics
	}
	scalarValues := map[string]attr.Value{}
	identify_original_ipScalar := types.BoolNull()
	if scalars.IDentifyOriginalIp != nil {
		identify_original_ipScalar = types.BoolValue(*scalars.IDentifyOriginalIp)
	}
	scalarValues["identify_original_ip"] = identify_original_ipScalar
	source_portScalar := types.BoolNull()
	if scalars.SourcePort != nil {
		source_portScalar = types.BoolValue(*scalars.SourcePort)
	}
	scalarValues["source_port"] = source_portScalar
	scalarValues["status"] = types.BoolValue(scalars.Status)
	x_forwarded_forScalar := types.BoolNull()
	if scalars.XForwardedFor != nil {
		x_forwarded_forScalar = types.BoolValue(*scalars.XForwardedFor)
	}
	scalarValues["x_forwarded_for"] = x_forwarded_forScalar
	x_forwarded_portScalar := types.BoolNull()
	if scalars.XForwardedPort != nil {
		x_forwarded_portScalar = types.BoolValue(*scalars.XForwardedPort)
	}
	scalarValues["x_forwarded_port"] = x_forwarded_portScalar
	x_headerScalar := types.StringNull()
	if scalars.XHeader != nil {
		x_headerScalar = types.StringValue(*scalars.XHeader)
	}
	scalarValues["x_header"] = x_headerScalar
	x_real_ipScalar := types.BoolNull()
	if scalars.XRealIp != nil {
		x_real_ipScalar = types.BoolValue(*scalars.XRealIp)
	}
	scalarValues["x_real_ip"] = x_real_ipScalar

	ruleListList := types.ObjectNull(rewritingRequestsRuleListWrapperAttributeTypes)
	if owned.RuleList {
		items, itemDiagnostics := rewritingRequestsDecodeRuleList(result.Configs["rule_list"])
		diagnostics.Append(itemDiagnostics...)
		subItemOwnedMasks := make(map[string][]bool)
		subItemOwnedMasks["RemoveHeader"] = make([]bool, len(items.Items))
		if ownership.Source == wafmodule.OwnershipConfigured || ownership.Source == wafmodule.OwnershipPriorState {
			ownershipConfigsValue, ownershipConfigsDiagnostics := wafmodule.OwnershipConfigs(ctx, ownership)
			diagnostics.Append(ownershipConfigsDiagnostics...)
			if !ownershipConfigsValue.IsNull() && !ownershipConfigsValue.IsUnknown() {
				var ownershipConfigs rewritingRequestsConfigsModel
				diagnostics.Append(ownershipConfigsValue.As(ctx, &ownershipConfigs, basetypes.ObjectAsOptions{})...)
				if !ownershipConfigs.RuleList.IsNull() && !ownershipConfigs.RuleList.IsUnknown() {
					var ownershipWrapper rewritingRequestsWrapperModel
					diagnostics.Append(ownershipConfigs.RuleList.As(ctx, &ownershipWrapper, basetypes.ObjectAsOptions{})...)
					if !ownershipWrapper.Items.IsNull() && !ownershipWrapper.Items.IsUnknown() {
						var ownershipItems []rewritingRequestsRuleListItemModel
						diagnostics.Append(ownershipWrapper.Items.ElementsAs(ctx, &ownershipItems, false)...)
						for i, ci := range ownershipItems {
							if i < len(subItemOwnedMasks["RemoveHeader"]) && !ci.RemoveHeader.IsNull() {
								subItemOwnedMasks["RemoveHeader"][i] = true
							}
						}
					}
				}
			}
		} else {
			for i := range subItemOwnedMasks["RemoveHeader"] {
				subItemOwnedMasks["RemoveHeader"][i] = true
			}
		}
		// Decode nested sub-item arrays for owned items only (fail-closed on
		// unknown keys). Unowned items leave the nested array nil (opaque).
		// Decode item-level scalar-string-arrays for owned items only (fail-
		// closed on unknown keys). Unowned items leave the array nil (opaque).
		ruleListRawISA := result.Configs["rule_list"]
		if len(ruleListRawISA) > 0 && !rewritingRequestsJSONNull(ruleListRawISA) {
			var ruleListRawItemsISA []json.RawMessage
			if err := json.Unmarshal(ruleListRawISA, &ruleListRawItemsISA); err == nil {
				for _, ri := range ruleListRawItemsISA {
					var itemObj map[string]json.RawMessage
					if err := json.Unmarshal(ri, &itemObj); err != nil {
						continue
					}
					// Indexed collection: match by idx (decoded items are
					// sorted by idx, raw items are in wire order).
					rawIdxInt, ok := rewritingRequestsParseIdx(itemObj["idx"], "rule_list item")
					if !ok {
						continue
					}
					for j := range items.Items {
						if int(items.Items[j].Index) == int(rawIdxInt) {

							if j < len(subItemOwnedMasks["RemoveHeader"]) && subItemOwnedMasks["RemoveHeader"][j] {
								remove_headerDecoded := rewritingRequestsRuleListDecodeItemStringArrayRemoveHeader(itemObj["remove_header"], fmt.Sprintf("rule_list item %d remove_header", j+1), &diagnostics)
								if remove_headerDecoded != nil {
									items.Items[j].RemoveHeader, _ = json.Marshal(remove_headerDecoded)
								}
							}
							break
						}
					}
				}
			}
		}
		ruleListList, itemDiagnostics = rewritingRequestsRuleListWrapperValue(items, subItemOwnedMasks)
		diagnostics.Append(itemDiagnostics...)
	}
	scalarValues["rule_list"] = ruleListList
	if diagnostics.HasError() {
		return nil, diagnostics
	}
	model.Configs, diagnostics = types.ObjectValue(rewritingRequestsConfigAttributeTypes, scalarValues)
	return &model, diagnostics
}

func (codec rewritingRequestsCodec) FlattenTemplate(ctx context.Context, templateID string, result client.WAFModuleResult, ownership wafmodule.OwnershipContext) (any, diag.Diagnostics) {
	result.Template = false
	appModelAny, diagnostics := codec.Flatten(ctx, templateID, result, ownership)
	if diagnostics.HasError() || appModelAny == nil {
		return nil, diagnostics
	}
	appModel, ok := appModelAny.(*rewritingRequestsResourceModel)
	if !ok {
		diagnostics.AddError("Unable to flatten rewriting requests template configuration", fmt.Sprintf("Unexpected app model type %T.", appModelAny))
		return nil, diagnostics
	}
	return &wafmodule.TemplateModel{
		TemplateID: types.StringValue(templateID),
		Configs:    appModel.Configs,
	}, diagnostics
}

func (patch rewritingRequestsPatch) Apply(_ context.Context, result *client.WAFModuleResult) diag.Diagnostics {
	var diagnostics diag.Diagnostics
	if result == nil {
		diagnostics.AddError("Unable to merge rewriting requests configuration", "The current API result was nil.")
		return diagnostics
	}
	set := func(name string, value any) {
		if err := result.SetConfig(name, value); err != nil {
			diagnostics.AddError("Unable to merge rewriting requests configuration", fmt.Sprintf("Unable to encode %s: %v", name, err))
		}
	}
	if patch.IDentifyOriginalIp.Set {
		set("identify_original_ip", patch.IDentifyOriginalIp.Value)
	}
	if patch.SourcePort.Set {
		set("source_port", patch.SourcePort.Value)
	}
	if patch.Status.Set {
		set("status", patch.Status.Value)
	}
	if patch.XForwardedFor.Set {
		set("x_forwarded_for", patch.XForwardedFor.Value)
	}
	if patch.XForwardedPort.Set {
		set("x_forwarded_port", patch.XForwardedPort.Value)
	}
	if patch.XHeader.Set {
		set("x_header", patch.XHeader.Value)
	}
	if patch.XRealIp.Set {
		set("x_real_ip", patch.XRealIp.Value)
	}

	if patch.RuleList.Set {
		// Merge preserved nested sub-item arrays / item string-arrays from the
		// fresh GET into a per-attempt clone of the patch items. This ensures
		// opaque preservation (the PUT carries the fresh GET's nested raw
		// value, including unknown keys and null) and is safe across 409
		// retries (the original patch is not mutated; the clone is rebuilt
		// from each fresh GET).
		ruleListGetRaw := result.Configs["rule_list"]
		ruleListPatchItems := make([]rewritingRequestsRuleListWireItem, len(patch.RuleList.Items))
		copy(ruleListPatchItems, patch.RuleList.Items)
		if len(ruleListGetRaw) > 0 && !rewritingRequestsJSONNull(ruleListGetRaw) {
			var ruleListGetItems []map[string]json.RawMessage
			if err := json.Unmarshal(ruleListGetRaw, &ruleListGetItems); err == nil {
				// Preserve omitted nested arrays by matching each patch item to a
				// unique unconsumed fresh-GET item by its "unchanged projection"
				// (canonical content of every known parent field except the
				// wire-only idx and the nested ownership fields). There is no
				// proven stable identity field (idx is regenerated sequentially;
				// cat/name are not unique), so preservation matches by unchanged
				// content, not identity. A unique unconsumed match is required:
				// a changed, new, reordered-differently, or duplicate item with
				// an omitted nested wrapper cannot be matched safely, so the
				// apply is refused (omission means preserve; an ambiguous mapping
				// must fail rather than be guessed). One remote item cannot
				// satisfy two patch items (consumed map).
				ruleListConsumed := make(map[int]bool, len(ruleListGetItems))
				for i := range ruleListPatchItems {
					// Determine whether any nested ownership field is omitted for
					// this patch item; only then is preservation needed.
					ruleListOmitAny := false
					if len(ruleListPatchItems[i].RemoveHeader) == 0 {
						ruleListOmitAny = true
					}
					if ruleListOmitAny && len(ruleListGetItems) > 0 {
						// Only preserve when the fresh GET has existing items to
						// preserve from. When the remote collection is empty,
						// every patch item is new: an omitted nested wrapper has
						// nothing to preserve and stays omitted (no refusal).
						match, matchIndex, ok := rewritingRequestsRuleListMatchGetItem(ruleListPatchItems[i], ruleListGetItems, ruleListConsumed)
						if !ok {
							diagnostics.AddError("Cannot preserve omitted nested array",
								fmt.Sprintf("configs.rule_list.item[%d] omits a nested ownership wrapper, but the provider could not uniquely match the parent item to the fresh GET by its unchanged content. Apply was refused because omission means preserve. Configure each omitted wrapper explicitly: an empty wrapper sends []; a populated wrapper replaces the array.", i+1))
							return diagnostics
						}
						ruleListConsumed[matchIndex] = true
						if len(ruleListPatchItems[i].RemoveHeader) == 0 {
							if subRaw, ok := match["remove_header"]; ok && len(subRaw) > 0 {
								ruleListPatchItems[i].RemoveHeader = subRaw
							}
						}
					}
				}
			}
		}
		set("rule_list", ruleListPatchItems)
	}
	return diagnostics
}

func rewritingRequestsValidateConfiguredRuleList(ctx context.Context, wrapper types.Object) diag.Diagnostics {
	var diagnostics diag.Diagnostics
	if wrapper.IsNull() || wrapper.IsUnknown() {
		return diagnostics
	}
	var value rewritingRequestsWrapperModel
	diagnostics.Append(wrapper.As(ctx, &value, basetypes.ObjectAsOptions{})...)
	if diagnostics.HasError() || value.Items.IsNull() || value.Items.IsUnknown() {
		return diagnostics
	}
	if len(value.Items.Elements()) > rewritingRequestsRuleListMaxItems {
		diagnostics.AddError("Invalid rewriting requests rule_list", fmt.Sprintf("rule_list may contain at most %d item blocks.", rewritingRequestsRuleListMaxItems))
		return diagnostics
	}
	var items []rewritingRequestsRuleListItemModel
	diagnostics.Append(value.Items.ElementsAs(ctx, &items, false)...)
	if diagnostics.HasError() {
		return diagnostics
	}
	for index, item := range items {
		location := fmt.Sprintf("rule_list item %d", index+1)
		if !item.Action.IsNull() && !item.Action.IsUnknown() {
			if !rewritingRequestsRuleListActionValid(item.Action.ValueString()) {
				diagnostics.AddError("Invalid rewriting requests item", location+" action must be one of redirect-301, redirect-301-advanced, redirect-host, rewrite-header-advanced, rewrite-host, rewrite-refer, rewrite-response-header, rewrite-url.")
			}
		}
		if !item.HostExpression.IsNull() && !item.HostExpression.IsUnknown() {
			if utf8.RuneCountInString(item.HostExpression.ValueString()) > 255 {
				diagnostics.AddError("Invalid rewriting requests item", fmt.Sprintf("%s host_expression exceeds %d UTF-8 characters.", location, 255))
			}
		}
		if !item.InsertHeaderName.IsNull() && !item.InsertHeaderName.IsUnknown() {
			if utf8.RuneCountInString(item.InsertHeaderName.ValueString()) > 255 {
				diagnostics.AddError("Invalid rewriting requests item", fmt.Sprintf("%s insert_header_name exceeds %d UTF-8 characters.", location, 255))
			}
		}
		if !item.InsertHeaderValue.IsNull() && !item.InsertHeaderValue.IsUnknown() {
			if utf8.RuneCountInString(item.InsertHeaderValue.ValueString()) > 1023 {
				diagnostics.AddError("Invalid rewriting requests item", fmt.Sprintf("%s insert_header_value exceeds %d UTF-8 characters.", location, 1023))
			}
		}
		if !item.LocationExpression.IsNull() && !item.LocationExpression.IsUnknown() {
			if utf8.RuneCountInString(item.LocationExpression.ValueString()) > 255 {
				diagnostics.AddError("Invalid rewriting requests item", fmt.Sprintf("%s location_expression exceeds %d UTF-8 characters.", location, 255))
			}
		}
		if !item.Name.IsNull() && !item.Name.IsUnknown() {
			if utf8.RuneCountInString(item.Name.ValueString()) > 39 {
				diagnostics.AddError("Invalid rewriting requests item", fmt.Sprintf("%s name exceeds %d UTF-8 characters.", location, 39))
			}
		}
		if !item.Protocol.IsNull() && !item.Protocol.IsUnknown() {
			if !rewritingRequestsRuleListProtocolValid(item.Protocol.ValueString()) {
				diagnostics.AddError("Invalid rewriting requests item", location+" protocol must be one of HTTP, HTTPS.")
			}
		}
		if !item.RefererExpression.IsNull() && !item.RefererExpression.IsUnknown() {
			if utf8.RuneCountInString(item.RefererExpression.ValueString()) > 255 {
				diagnostics.AddError("Invalid rewriting requests item", fmt.Sprintf("%s referer_expression exceeds %d UTF-8 characters.", location, 255))
			}
		}
		if !item.RewriteFrom.IsNull() && !item.RewriteFrom.IsUnknown() {
			if utf8.RuneCountInString(item.RewriteFrom.ValueString()) > 255 {
				diagnostics.AddError("Invalid rewriting requests item", fmt.Sprintf("%s rewrite_from exceeds %d UTF-8 characters.", location, 255))
			}
		}
		if !item.RewriteHost.IsNull() && !item.RewriteHost.IsUnknown() {
			if utf8.RuneCountInString(item.RewriteHost.ValueString()) > 255 {
				diagnostics.AddError("Invalid rewriting requests item", fmt.Sprintf("%s rewrite_host exceeds %d UTF-8 characters.", location, 255))
			}
		}
		if !item.RewriteLocation.IsNull() && !item.RewriteLocation.IsUnknown() {
			if utf8.RuneCountInString(item.RewriteLocation.ValueString()) > 255 {
				diagnostics.AddError("Invalid rewriting requests item", fmt.Sprintf("%s rewrite_location exceeds %d UTF-8 characters.", location, 255))
			}
		}
		if !item.RewriteReferer.IsNull() && !item.RewriteReferer.IsUnknown() {
			if utf8.RuneCountInString(item.RewriteReferer.ValueString()) > 255 {
				diagnostics.AddError("Invalid rewriting requests item", fmt.Sprintf("%s rewrite_referer exceeds %d UTF-8 characters.", location, 255))
			}
		}
		if !item.RewriteTo.IsNull() && !item.RewriteTo.IsUnknown() {
			if utf8.RuneCountInString(item.RewriteTo.ValueString()) > 255 {
				diagnostics.AddError("Invalid rewriting requests item", fmt.Sprintf("%s rewrite_to exceeds %d UTF-8 characters.", location, 255))
			}
		}
		if !item.RewriteURL.IsNull() && !item.RewriteURL.IsUnknown() {
			if utf8.RuneCountInString(item.RewriteURL.ValueString()) > 255 {
				diagnostics.AddError("Invalid rewriting requests item", fmt.Sprintf("%s rewrite_url exceeds %d UTF-8 characters.", location, 255))
			}
		}
		if !item.URLExpression.IsNull() && !item.URLExpression.IsUnknown() {
			if utf8.RuneCountInString(item.URLExpression.ValueString()) > 255 {
				diagnostics.AddError("Invalid rewriting requests item", fmt.Sprintf("%s url_expression exceeds %d UTF-8 characters.", location, 255))
			}
		}
	}
	return diagnostics
}

func rewritingRequestsBuildConfiguredRuleList(ctx context.Context, configured, planned types.Object, diagnostics diag.Diagnostics) (rewritingRequestsRuleListOwnedList, diag.Diagnostics) {
	if configured.IsNull() {
		return rewritingRequestsRuleListOwnedList{}, diagnostics
	}
	if configured.IsUnknown() {
		diagnostics.AddError("Unknown rewriting requests rule_list", "The rule_list ownership wrapper must be known during apply.")
		return rewritingRequestsRuleListOwnedList{}, diagnostics
	}
	if planned.IsNull() || planned.IsUnknown() {
		diagnostics.AddError("Unknown rewriting requests rule_list", "The planned rule_list ownership wrapper must be known during apply.")
		return rewritingRequestsRuleListOwnedList{}, diagnostics
	}
	var configWrapper, planWrapper rewritingRequestsWrapperModel
	diagnostics.Append(configured.As(ctx, &configWrapper, basetypes.ObjectAsOptions{})...)
	diagnostics.Append(planned.As(ctx, &planWrapper, basetypes.ObjectAsOptions{})...)
	if diagnostics.HasError() {
		return rewritingRequestsRuleListOwnedList{}, diagnostics
	}
	if configWrapper.Items.IsUnknown() || planWrapper.Items.IsUnknown() {
		diagnostics.AddError("Unknown rewriting requests rule_list", "The rule_list item blocks must be known during apply.")
		return rewritingRequestsRuleListOwnedList{}, diagnostics
	}
	if configWrapper.Items.IsNull() {
		return rewritingRequestsRuleListOwnedList{Set: true, Items: []rewritingRequestsRuleListWireItem{}}, diagnostics
	}

	var configItems, planItems []rewritingRequestsRuleListItemModel
	diagnostics.Append(configWrapper.Items.ElementsAs(ctx, &configItems, false)...)
	if planWrapper.Items.IsNull() {
		if len(configItems) != 0 {
			diagnostics.AddError("Invalid rewriting requests rule_list", "The planned item list unexpectedly became null.")
		}
		return rewritingRequestsRuleListOwnedList{Set: true, Items: []rewritingRequestsRuleListWireItem{}}, diagnostics
	}
	diagnostics.Append(planWrapper.Items.ElementsAs(ctx, &planItems, false)...)
	if diagnostics.HasError() {
		return rewritingRequestsRuleListOwnedList{}, diagnostics
	}
	if len(configItems) != len(planItems) {
		diagnostics.AddError("Invalid rewriting requests rule_list", "Configured and planned item counts differ.")
		return rewritingRequestsRuleListOwnedList{}, diagnostics
	}
	if len(configItems) > rewritingRequestsRuleListMaxItems {
		diagnostics.AddError("Invalid rewriting requests rule_list", fmt.Sprintf("rule_list may contain at most %d item blocks.", rewritingRequestsRuleListMaxItems))
		return rewritingRequestsRuleListOwnedList{}, diagnostics
	}

	items := make([]rewritingRequestsRuleListWireItem, 0, len(configItems))
	for index := range configItems {
		configuredItem := configItems[index]
		plannedItem := planItems[index]
		location := fmt.Sprintf("rule_list item %d", index+1)
		item := rewritingRequestsRuleListWireItem{
			Index: rewritingRequestsIdx(index + 1),
		}
		item.Action = rewritingRequestsPlannedOptionalString(configuredItem.Action, plannedItem.Action, location+" action", 0, &diagnostics)
		if item.Action != nil && !rewritingRequestsRuleListActionValid(*item.Action) {
			diagnostics.AddError("Invalid rewriting requests item", location+" action must be one of redirect-301, redirect-301-advanced, redirect-host, rewrite-header-advanced, rewrite-host, rewrite-refer, rewrite-response-header, rewrite-url.")
		}
		header_statusValue, ok := rewritingRequestsPlannedOptionalBool(configuredItem.HeaderStatus, plannedItem.HeaderStatus, location+" header_status", &diagnostics)
		if ok {
			item.HeaderStatus = header_statusValue
		}
		item.HostExpression = rewritingRequestsPlannedOptionalString(configuredItem.HostExpression, plannedItem.HostExpression, location+" host_expression", 255, &diagnostics)
		host_filterValue, ok := rewritingRequestsPlannedOptionalBool(configuredItem.HostFilter, plannedItem.HostFilter, location+" host_filter", &diagnostics)
		if ok {
			item.HostFilter = host_filterValue
		}
		host_statusValue, ok := rewritingRequestsPlannedOptionalBool(configuredItem.HostStatus, plannedItem.HostStatus, location+" host_status", &diagnostics)
		if ok {
			item.HostStatus = host_statusValue
		}
		item.InsertHeaderName = rewritingRequestsPlannedOptionalString(configuredItem.InsertHeaderName, plannedItem.InsertHeaderName, location+" insert_header_name", 255, &diagnostics)
		item.InsertHeaderValue = rewritingRequestsPlannedOptionalString(configuredItem.InsertHeaderValue, plannedItem.InsertHeaderValue, location+" insert_header_value", 1023, &diagnostics)
		item.LocationExpression = rewritingRequestsPlannedOptionalString(configuredItem.LocationExpression, plannedItem.LocationExpression, location+" location_expression", 255, &diagnostics)
		location_filterValue, ok := rewritingRequestsPlannedOptionalBool(configuredItem.LocationFilter, plannedItem.LocationFilter, location+" location_filter", &diagnostics)
		if ok {
			item.LocationFilter = location_filterValue
		}
		location_statusValue, ok := rewritingRequestsPlannedOptionalBool(configuredItem.LocationStatus, plannedItem.LocationStatus, location+" location_status", &diagnostics)
		if ok {
			item.LocationStatus = location_statusValue
		}
		item.Name = rewritingRequestsPlannedOptionalString(configuredItem.Name, plannedItem.Name, location+" name", 39, &diagnostics)
		item.Protocol = rewritingRequestsPlannedOptionalString(configuredItem.Protocol, plannedItem.Protocol, location+" protocol", 0, &diagnostics)
		if item.Protocol == nil {
			protocolDefault := "HTTP"
			item.Protocol = &protocolDefault
		}
		if item.Protocol != nil && !rewritingRequestsRuleListProtocolValid(*item.Protocol) {
			diagnostics.AddError("Invalid rewriting requests item", location+" protocol must be one of HTTP, HTTPS.")
		}
		protocol_filterValue, ok := rewritingRequestsPlannedOptionalBool(configuredItem.ProtocolFilter, plannedItem.ProtocolFilter, location+" protocol_filter", &diagnostics)
		if ok {
			item.ProtocolFilter = protocol_filterValue
		}
		item.RefererExpression = rewritingRequestsPlannedOptionalString(configuredItem.RefererExpression, plannedItem.RefererExpression, location+" referer_expression", 255, &diagnostics)
		referer_filterValue, ok := rewritingRequestsPlannedOptionalBool(configuredItem.RefererFilter, plannedItem.RefererFilter, location+" referer_filter", &diagnostics)
		if ok {
			item.RefererFilter = referer_filterValue
		}
		referer_statusValue, ok := rewritingRequestsPlannedOptionalBool(configuredItem.RefererStatus, plannedItem.RefererStatus, location+" referer_status", &diagnostics)
		if ok {
			item.RefererStatus = referer_statusValue
		}

		remove_headerBuilt := rewritingRequestsRuleListBuildItemStringArrayRemoveHeader(ctx, configuredItem.RemoveHeader, plannedItem.RemoveHeader, location, &diagnostics)
		if remove_headerBuilt.Set {
			item.RemoveHeader, _ = json.Marshal(remove_headerBuilt.Items)
		}
		item.RewriteFrom = rewritingRequestsPlannedOptionalString(configuredItem.RewriteFrom, plannedItem.RewriteFrom, location+" rewrite_from", 255, &diagnostics)
		item.RewriteHost = rewritingRequestsPlannedOptionalString(configuredItem.RewriteHost, plannedItem.RewriteHost, location+" rewrite_host", 255, &diagnostics)
		item.RewriteLocation = rewritingRequestsPlannedOptionalString(configuredItem.RewriteLocation, plannedItem.RewriteLocation, location+" rewrite_location", 255, &diagnostics)
		item.RewriteReferer = rewritingRequestsPlannedOptionalString(configuredItem.RewriteReferer, plannedItem.RewriteReferer, location+" rewrite_referer", 255, &diagnostics)
		item.RewriteTo = rewritingRequestsPlannedOptionalString(configuredItem.RewriteTo, plannedItem.RewriteTo, location+" rewrite_to", 255, &diagnostics)
		item.RewriteURL = rewritingRequestsPlannedOptionalString(configuredItem.RewriteURL, plannedItem.RewriteURL, location+" rewrite_url", 255, &diagnostics)
		item.URLExpression = rewritingRequestsPlannedOptionalString(configuredItem.URLExpression, plannedItem.URLExpression, location+" url_expression", 255, &diagnostics)
		url_filterValue, ok := rewritingRequestsPlannedOptionalBool(configuredItem.URLFilter, plannedItem.URLFilter, location+" url_filter", &diagnostics)
		if ok {
			item.URLFilter = url_filterValue
		}
		url_statusValue, ok := rewritingRequestsPlannedOptionalBool(configuredItem.URLStatus, plannedItem.URLStatus, location+" url_status", &diagnostics)
		if ok {
			item.URLStatus = url_statusValue
		}
		url_translationValue, ok := rewritingRequestsPlannedOptionalBool(configuredItem.URLTranslation, plannedItem.URLTranslation, location+" url_translation", &diagnostics)
		if ok {
			item.URLTranslation = url_translationValue
		}
		items = append(items, item)
	}
	return rewritingRequestsRuleListOwnedList{Set: true, Items: items}, diagnostics
}

func rewritingRequestsRuleListBuildItemStringArrayRemoveHeader(ctx context.Context, configured, planned types.Object, location string, diagnostics *diag.Diagnostics) rewritingRequestsRuleListRemoveHeaderStringArrayOwnedList {
	if configured.IsNull() {
		return rewritingRequestsRuleListRemoveHeaderStringArrayOwnedList{}
	}
	if configured.IsUnknown() || planned.IsNull() || planned.IsUnknown() {
		diagnostics.AddError("Invalid rewriting requests item", location+" remove_header ownership wrapper must be known during apply.")
		return rewritingRequestsRuleListRemoveHeaderStringArrayOwnedList{}
	}
	var configWrapper, planWrapper rewritingRequestsWrapperModel
	diagnostics.Append(configured.As(ctx, &configWrapper, basetypes.ObjectAsOptions{})...)
	diagnostics.Append(planned.As(ctx, &planWrapper, basetypes.ObjectAsOptions{})...)
	if diagnostics.HasError() {
		return rewritingRequestsRuleListRemoveHeaderStringArrayOwnedList{}
	}
	if configWrapper.Items.IsNull() {
		return rewritingRequestsRuleListRemoveHeaderStringArrayOwnedList{Set: true, Items: []string{}}
	}
	var configItems []rewritingRequestsRuleListRemoveHeaderItemModel
	diagnostics.Append(configWrapper.Items.ElementsAs(ctx, &configItems, false)...)
	if diagnostics.HasError() {
		return rewritingRequestsRuleListRemoveHeaderStringArrayOwnedList{}
	}
	// planItems carries the resolved plan values; when a config item attribute
	// is unknown (a computed reference resolved by apply time), fall back to the
	// planned value so valid computed headers are not rejected. Mirrors the
	// other generated item build helpers.
	var planItems []rewritingRequestsRuleListRemoveHeaderItemModel
	diagnostics.Append(planWrapper.Items.ElementsAs(ctx, &planItems, false)...)
	if diagnostics.HasError() {
		return rewritingRequestsRuleListRemoveHeaderStringArrayOwnedList{}
	}
	if len(configItems) > rewritingRequestsRuleListRemoveHeaderMaxItems {
		diagnostics.AddError("Invalid rewriting requests item", fmt.Sprintf("%s remove_header may contain at most %d item blocks.", location, rewritingRequestsRuleListRemoveHeaderMaxItems))
		return rewritingRequestsRuleListRemoveHeaderStringArrayOwnedList{}
	}
	items := make([]string, 0, len(configItems))
	for index, ci := range configItems {
		headerValue := ci.Header
		if headerValue.IsUnknown() && index < len(planItems) && !planItems[index].Header.IsUnknown() {
			headerValue = planItems[index].Header
		}
		if headerValue.IsNull() || headerValue.IsUnknown() {
			diagnostics.AddError("Invalid rewriting requests item", location+" remove_header item header is required.")
			continue
		}
		value := headerValue.ValueString()
		if utf8.RuneCountInString(value) > 63 {
			diagnostics.AddError("Invalid rewriting requests item", fmt.Sprintf("%s remove_header item header must be at most %d UTF-8 characters.", location, 63))
			continue
		}
		items = append(items, value)
	}
	return rewritingRequestsRuleListRemoveHeaderStringArrayOwnedList{Set: true, Items: items}
}

func rewritingRequestsRuleListDecodeItemStringArrayRemoveHeader(raw json.RawMessage, location string, diagnostics *diag.Diagnostics) []string {
	if len(raw) == 0 {
		return nil
	}
	if rewritingRequestsJSONNull(raw) {
		diagnostics.AddError("Malformed rewriting requests result", location+" was null but the reviewed array is not nullable.")
		return nil
	}
	var rawItems []json.RawMessage
	if err := json.Unmarshal(raw, &rawItems); err != nil {
		diagnostics.AddError("Malformed rewriting requests result", location+" was not an array of strings.")
		return nil
	}
	items := make([]string, 0, len(rawItems))
	for _, element := range rawItems {
		// Reject JSON null elements: the item string is not nullable, so a null
		// entry must fail closed rather than being coerced to an empty string.
		if len(bytes.TrimSpace(element)) == 0 || rewritingRequestsJSONNull(element) {
			diagnostics.AddError("Malformed rewriting requests result", location+" contained a null element, but the reviewed item string is not nullable.")
			return nil
		}
		var v string
		if err := json.Unmarshal(element, &v); err != nil {
			diagnostics.AddError("Malformed rewriting requests result", location+" was not an array of strings.")
			return nil
		}
		items = append(items, v)
	}
	if len(items) > rewritingRequestsRuleListRemoveHeaderMaxItems {
		diagnostics.AddError("Malformed rewriting requests result", fmt.Sprintf("%s contained more than %d items.", location, rewritingRequestsRuleListRemoveHeaderMaxItems))
		return nil
	}
	for _, v := range items {
		if utf8.RuneCountInString(v) > 63 {
			diagnostics.AddError("Malformed rewriting requests result", fmt.Sprintf("%s contained a string longer than %d UTF-8 characters.", location, 63))
		}
	}
	return items
}

func rewritingRequestsRuleListRemoveHeaderItemStringArrayWrapperValue(itemsRaw json.RawMessage) (types.Object, diag.Diagnostics) {
	var diagnostics diag.Diagnostics
	if len(itemsRaw) == 0 {
		return types.ObjectNull(rewritingRequestsRuleListRemoveHeaderWrapperAttributeTypes), diagnostics
	}
	var items []string
	if err := json.Unmarshal(itemsRaw, &items); err != nil {
		diagnostics.AddError("Malformed rewriting requests result", "The successful API result contained a non-array remove_header value.")
		return types.ObjectNull(rewritingRequestsRuleListRemoveHeaderWrapperAttributeTypes), diagnostics
	}
	elements := make([]attr.Value, 0, len(items))
	for _, v := range items {
		object, objectDiagnostics := types.ObjectValue(rewritingRequestsRuleListRemoveHeaderItemAttributeTypes, map[string]attr.Value{"header": types.StringValue(v)})
		diagnostics.Append(objectDiagnostics...)
		elements = append(elements, object)
	}
	list, listDiagnostics := types.ListValue(types.ObjectType{AttrTypes: rewritingRequestsRuleListRemoveHeaderItemAttributeTypes}, elements)
	diagnostics.Append(listDiagnostics...)
	wrapper, wrapperDiagnostics := types.ObjectValue(rewritingRequestsRuleListRemoveHeaderWrapperAttributeTypes, map[string]attr.Value{"item": list})
	diagnostics.Append(wrapperDiagnostics...)
	return wrapper, diagnostics
}
func rewritingRequestsConfiguredString(configured, planned types.String, name string, diagnostics diag.Diagnostics) (client.Optional[string], diag.Diagnostics) {
	value, valueDiagnostics := wafmodule.ConfiguredString(configured, planned, name)
	diagnostics.Append(valueDiagnostics...)
	return value, diagnostics
}
func rewritingRequestsConfiguredBool(configured, planned types.Bool, name string, diagnostics diag.Diagnostics) (client.Optional[bool], diag.Diagnostics) {
	value, valueDiagnostics := wafmodule.ConfiguredBool(configured, planned, name)
	diagnostics.Append(valueDiagnostics...)
	return value, diagnostics
}
func rewritingRequestsPlannedRequiredString(configured, planned types.String, name string, diagnostics *diag.Diagnostics) (string, bool) {
	if configured.IsNull() {
		diagnostics.AddError("Invalid rewriting requests item", "The required "+name+" is null.")
		return "", false
	}
	if configured.IsUnknown() {
		if planned.IsNull() || planned.IsUnknown() {
			diagnostics.AddError("Unknown rewriting requests item", "The configured "+name+" is still unknown during apply.")
			return "", false
		}
		return planned.ValueString(), true
	}
	return configured.ValueString(), true
}
func rewritingRequestsPlannedOptionalString(configured, planned types.String, name string, maximum int, diagnostics *diag.Diagnostics) *string {
	if configured.IsNull() {
		// Omission preserves the prior state value carried into the plan by
		// use_state_for_unknown; a null planned value (e.g. a clear-string
		// modifier) drops the field so the backend removes it.
		if !planned.IsNull() && !planned.IsUnknown() {
			value := planned.ValueString()
			if maximum > 0 && utf8.RuneCountInString(value) > maximum {
				diagnostics.AddError("Invalid rewriting requests item", fmt.Sprintf("The %s exceeds %d UTF-8 characters.", name, maximum))
			}
			return &value
		}
		return nil
	}
	value := ""
	if configured.IsUnknown() {
		if planned.IsNull() {
			return nil
		}
		if planned.IsUnknown() {
			diagnostics.AddError("Unknown rewriting requests item", "The configured "+name+" is still unknown during apply.")
			return nil
		}
		value = planned.ValueString()
	} else {
		value = configured.ValueString()
	}
	if maximum > 0 && utf8.RuneCountInString(value) > maximum {
		diagnostics.AddError("Invalid rewriting requests item", fmt.Sprintf("The %s exceeds %d UTF-8 characters.", name, maximum))
	}
	return &value
}
