func rewritingRequestsDecodeRuleList(raw json.RawMessage) (rewritingRequestsRuleListOwnedList, diag.Diagnostics) {
	var diagnostics diag.Diagnostics
	if len(raw) == 0 {
		return rewritingRequestsRuleListOwnedList{}, diagnostics
	}
	if rewritingRequestsJSONNull(raw) {
		diagnostics.AddError("Malformed rewriting requests result", "The successful API result contained null rule_list instead of an array.")
		return rewritingRequestsRuleListOwnedList{}, diagnostics
	}
	var rawItems []json.RawMessage
	if err := json.Unmarshal(raw, &rawItems); err != nil {
		diagnostics.AddError("Malformed rewriting requests result", "The successful API result contained a non-array rule_list value.")
		return rewritingRequestsRuleListOwnedList{}, diagnostics
	}
	if len(rawItems) > rewritingRequestsRuleListMaxItems {
		diagnostics.AddError("Malformed rewriting requests result", fmt.Sprintf("The successful API result contained more than %d rule_list items.", rewritingRequestsRuleListMaxItems))
		return rewritingRequestsRuleListOwnedList{}, diagnostics
	}

	items := make([]rewritingRequestsRuleListWireItem, 0, len(rawItems))
	seen := make(map[int]struct{}, len(rawItems))
	knownKeys := map[string]struct{}{
		"action":              {},
		"header_status":       {},
		"host_expression":     {},
		"host_filter":         {},
		"host_status":         {},
		"idx":                 {},
		"insert_header_name":  {},
		"insert_header_value": {},
		"location_expression": {},
		"location_filter":     {},
		"location_status":     {},
		"name":                {},
		"protocol":            {},
		"protocol_filter":     {},
		"referer_expression":  {},
		"referer_filter":      {},
		"referer_status":      {},
		"remove_header":       {},
		"rewrite_from":        {},
		"rewrite_host":        {},
		"rewrite_location":    {},
		"rewrite_referer":     {},
		"rewrite_to":          {},
		"rewrite_url":         {},
		"url_expression":      {},
		"url_filter":          {},
		"url_status":          {},
		"url_translation":     {},
	}
	for position, rawItem := range rawItems {
		location := fmt.Sprintf("rule_list item %d", position+1)
		var object map[string]json.RawMessage
		if err := json.Unmarshal(rawItem, &object); err != nil || object == nil {
			diagnostics.AddError("Malformed rewriting requests result", location+" was not an object.")
			continue
		}
		unknown := make([]string, 0)
		for key := range object {
			if _, ok := knownKeys[key]; !ok {
				unknown = append(unknown, key)
			}
		}
		sort.Strings(unknown)
		if len(unknown) != 0 {
			diagnostics.AddError("Unknown rewriting requests item field", location+" contained unsupported keys: "+strings.Join(unknown, ", ")+".")
			continue
		}
		index, ok := rewritingRequestsDecodeIndex(object["idx"], location, "string", &diagnostics)
		if !ok {
			continue
		}
		if _, duplicate := seen[index]; duplicate {
			diagnostics.AddError("Malformed rewriting requests result", fmt.Sprintf("%s used duplicate idx %d.", location, index))
			continue
		}
		seen[index] = struct{}{}
		item := rewritingRequestsRuleListWireItem{Index: rewritingRequestsIdx(index)}
		rewritingRequestsRejectItemNullUnlessNullable(object, "action", false, location, &diagnostics)
		item.Action = rewritingRequestsDecodeOptionalString(object, "action", location, 0, &diagnostics)
		if item.Action != nil && !rewritingRequestsRuleListActionValid(*item.Action) {
			diagnostics.AddError("Malformed rewriting requests result", location+" action was not one of redirect-301, redirect-301-advanced, redirect-host, rewrite-header-advanced, rewrite-host, rewrite-refer, rewrite-response-header, rewrite-url.")
		}
		rewritingRequestsRejectItemNullUnlessNullable(object, "header_status", false, location, &diagnostics)
		item.HeaderStatus = rewritingRequestsDecodeOptionalBool(object, "header_status", location, &diagnostics)
		rewritingRequestsRejectItemNullUnlessNullable(object, "host_expression", false, location, &diagnostics)
		item.HostExpression = rewritingRequestsDecodeOptionalString(object, "host_expression", location, 255, &diagnostics)
		rewritingRequestsRejectItemNullUnlessNullable(object, "host_filter", false, location, &diagnostics)
		item.HostFilter = rewritingRequestsDecodeOptionalBool(object, "host_filter", location, &diagnostics)
		rewritingRequestsRejectItemNullUnlessNullable(object, "host_status", false, location, &diagnostics)
		item.HostStatus = rewritingRequestsDecodeOptionalBool(object, "host_status", location, &diagnostics)
		rewritingRequestsRejectItemNullUnlessNullable(object, "insert_header_name", false, location, &diagnostics)
		item.InsertHeaderName = rewritingRequestsDecodeOptionalString(object, "insert_header_name", location, 255, &diagnostics)
		rewritingRequestsRejectItemNullUnlessNullable(object, "insert_header_value", false, location, &diagnostics)
		item.InsertHeaderValue = rewritingRequestsDecodeOptionalString(object, "insert_header_value", location, 1023, &diagnostics)
		rewritingRequestsRejectItemNullUnlessNullable(object, "location_expression", false, location, &diagnostics)
		item.LocationExpression = rewritingRequestsDecodeOptionalString(object, "location_expression", location, 255, &diagnostics)
		rewritingRequestsRejectItemNullUnlessNullable(object, "location_filter", false, location, &diagnostics)
		item.LocationFilter = rewritingRequestsDecodeOptionalBool(object, "location_filter", location, &diagnostics)
		rewritingRequestsRejectItemNullUnlessNullable(object, "location_status", false, location, &diagnostics)
		item.LocationStatus = rewritingRequestsDecodeOptionalBool(object, "location_status", location, &diagnostics)
		rewritingRequestsRejectItemNullUnlessNullable(object, "name", false, location, &diagnostics)
		item.Name = rewritingRequestsDecodeOptionalString(object, "name", location, 39, &diagnostics)
		rewritingRequestsRejectItemNullUnlessNullable(object, "protocol", false, location, &diagnostics)
		item.Protocol = rewritingRequestsDecodeOptionalStringWithDefault(object, "protocol", location, 0, "HTTP", &diagnostics)
		if item.Protocol != nil && !rewritingRequestsRuleListProtocolValid(*item.Protocol) {
			diagnostics.AddError("Malformed rewriting requests result", location+" protocol was not one of HTTP, HTTPS.")
		}
		rewritingRequestsRejectItemNullUnlessNullable(object, "protocol_filter", false, location, &diagnostics)
		item.ProtocolFilter = rewritingRequestsDecodeOptionalBool(object, "protocol_filter", location, &diagnostics)
		rewritingRequestsRejectItemNullUnlessNullable(object, "referer_expression", false, location, &diagnostics)
		item.RefererExpression = rewritingRequestsDecodeOptionalString(object, "referer_expression", location, 255, &diagnostics)
		rewritingRequestsRejectItemNullUnlessNullable(object, "referer_filter", false, location, &diagnostics)
		item.RefererFilter = rewritingRequestsDecodeOptionalBool(object, "referer_filter", location, &diagnostics)
		rewritingRequestsRejectItemNullUnlessNullable(object, "referer_status", false, location, &diagnostics)
		item.RefererStatus = rewritingRequestsDecodeOptionalBool(object, "referer_status", location, &diagnostics)
		// Item-level scalar-string-arrays are not decoded here; they are decoded
		// separately in the flatten when owned (fail-closed) and skipped in
		// ValidateResult (opaque when unowned).
		rewritingRequestsRejectItemNullUnlessNullable(object, "rewrite_from", false, location, &diagnostics)
		item.RewriteFrom = rewritingRequestsDecodeOptionalString(object, "rewrite_from", location, 255, &diagnostics)
		rewritingRequestsRejectItemNullUnlessNullable(object, "rewrite_host", false, location, &diagnostics)
		item.RewriteHost = rewritingRequestsDecodeOptionalString(object, "rewrite_host", location, 255, &diagnostics)
		rewritingRequestsRejectItemNullUnlessNullable(object, "rewrite_location", false, location, &diagnostics)
		item.RewriteLocation = rewritingRequestsDecodeOptionalString(object, "rewrite_location", location, 255, &diagnostics)
		rewritingRequestsRejectItemNullUnlessNullable(object, "rewrite_referer", false, location, &diagnostics)
		item.RewriteReferer = rewritingRequestsDecodeOptionalString(object, "rewrite_referer", location, 255, &diagnostics)
		rewritingRequestsRejectItemNullUnlessNullable(object, "rewrite_to", false, location, &diagnostics)
		item.RewriteTo = rewritingRequestsDecodeOptionalString(object, "rewrite_to", location, 255, &diagnostics)
		rewritingRequestsRejectItemNullUnlessNullable(object, "rewrite_url", false, location, &diagnostics)
		item.RewriteURL = rewritingRequestsDecodeOptionalString(object, "rewrite_url", location, 255, &diagnostics)
		rewritingRequestsRejectItemNullUnlessNullable(object, "url_expression", false, location, &diagnostics)
		item.URLExpression = rewritingRequestsDecodeOptionalString(object, "url_expression", location, 255, &diagnostics)
		rewritingRequestsRejectItemNullUnlessNullable(object, "url_filter", false, location, &diagnostics)
		item.URLFilter = rewritingRequestsDecodeOptionalBool(object, "url_filter", location, &diagnostics)
		rewritingRequestsRejectItemNullUnlessNullable(object, "url_status", false, location, &diagnostics)
		item.URLStatus = rewritingRequestsDecodeOptionalBool(object, "url_status", location, &diagnostics)
		rewritingRequestsRejectItemNullUnlessNullable(object, "url_translation", false, location, &diagnostics)
		item.URLTranslation = rewritingRequestsDecodeOptionalBool(object, "url_translation", location, &diagnostics)
		items = append(items, item)
	}
	if diagnostics.HasError() {
		return rewritingRequestsRuleListOwnedList{}, diagnostics
	}
	sort.Slice(items, func(i, j int) bool { return items[i].Index < items[j].Index })
	return rewritingRequestsRuleListOwnedList{Set: true, Items: items}, diagnostics
}

